select $q$P17$q$ as id, $q$Lecciones existentes que compara el cierre de A1, idénticas (19)$q$ as descripcion, $q$(ninguna distinta)$q$ as esperado, (select coalesce(string_agg(x.id, ','), '') from jsonb_to_recordset($l$[{"id":"a1-u01-l01","unit_id":"a1-u01","position":1,"title_es":"Hola y chau","objective_es":"Saludar y despedirte; decir sí y no.","intro":{"explanation":"Hello y hi son «hola»; hi es más informal. Para despedirte: goodbye o, más informal, bye.","examples":[{"target":"Hello, Ana!","base":"¡Hola, Ana!"},{"target":"Bye, Mom!","base":"¡Chau, mamá!"},{"target":"No, thank you.","base":"No, gracias."}]},"takeaways":["Saludás con hello o hi.","Te despedís con goodbye o bye.","Decís yes y no."],"_from":"20261119120000"},{"id":"a1-u01-l02","unit_id":"a1-u01","position":2,"title_es":"Momentos del día","objective_es":"Saludar según la hora del día.","intro":{"explanation":"Good morning es para la mañana, good afternoon para la tarde y good evening para saludar a la noche. Good night es sólo para despedirte o irte a dormir.","examples":[{"target":"Good morning, everyone!","base":"¡Buenos días a todos!"},{"target":"Good evening! Welcome.","base":"¡Buenas noches! Bienvenidos."},{"target":"Good night! See you tomorrow.","base":"¡Buenas noches! Hasta mañana."}]},"takeaways":["Saludás con good morning, good afternoon o good evening según la hora.","Usás good night sólo para despedirte."],"_from":"20261119120000"},{"id":"a1-u02-l04","unit_id":"a1-u02","position":5,"title_es":"He is, she is","objective_es":"Hablar de otras personas con is.","intro":{"explanation":"Con he, she e it el verbo es is: he is, she is, it is. Al hablar se contrae: he’s, she’s.","examples":[{"target":"He is a teacher.","base":"Él es profesor."},{"target":"She's my friend.","base":"Ella es mi amiga."}]},"takeaways":["Usás is con he, she e it.","Presentás a otra persona con he is o she is."],"_from":"20261119120000"},{"id":"a1-u02-l05","unit_id":"a1-u02","position":7,"title_es":"Negar y preguntar","objective_es":"Formar oraciones negativas y preguntas con to be.","intro":{"explanation":"Para negar, not va después de to be: I am not, she is not (isn’t). Para preguntar, el verbo va primero: Are you tired?","examples":[{"target":"I'm not tired.","base":"No estoy cansado."},{"target":"Is she a student?","base":"¿Ella es estudiante?"}]},"takeaways":["Negás con not después de am, is o are.","Preguntás poniendo el verbo primero: Are you…?"],"_from":"20261119120000"},{"id":"a1-u03-l03","unit_id":"a1-u03","position":4,"title_es":"Hasta veinte","objective_es":"Usar números más grandes: 11, 12, 15 y 20.","intro":{"explanation":"Eleven y twelve son especiales. Del 13 al 19 terminan en -teen: fifteen. Twenty es veinte. Ojo: fifteen (15) y fifty (50) suenan parecido.","examples":[{"target":"I have twelve friends.","base":"Tengo doce amigos."},{"target":"Fifteen dollars.","base":"Quince dólares."}]},"takeaways":["Decís 11, 12, 15 y 20.","Reconocés la terminación -teen."],"_from":"20261119120000"},{"id":"a1-u04-l04","unit_id":"a1-u04","position":5,"title_es":"Su, nuestro y su de ellos","objective_es":"Usar his, her, our y their.","intro":{"explanation":"En inglés «su» cambia según el dueño: his (de él), her (de ella), their (de ellos). Our es «nuestro» o «nuestra».","examples":[{"target":"His name is Tom.","base":"Su nombre (de él) es Tom."},{"target":"Our mother is a teacher.","base":"Nuestra madre es profesora."}]},"takeaways":["Elegís his o her según quién es el dueño.","Usás our y their."],"_from":"20261119120000"},{"id":"a1-u05-l02","unit_id":"a1-u05","position":2,"title_es":"A o an","objective_es":"Elegir a o an según el sonido de la palabra.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u06-l04","unit_id":"a1-u06","position":5,"title_es":"Hay una cama","objective_es":"Usar there is y there are.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u06-l05","unit_id":"a1-u06","position":7,"title_es":"¿Dónde está?","objective_es":"Ubicar cosas con in, on, under y next to.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u07-l04","unit_id":"a1-u07","position":5,"title_es":"Quiero un café","objective_es":"Pedir lo que querés con want y please.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u08-l02","unit_id":"a1-u08","position":2,"title_es":"Lo que hago","objective_es":"Trabajar, estudiar, leer, jugar, mirar, dormir y vivir.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u08-l04","unit_id":"a1-u08","position":5,"title_es":"No tomo café","objective_es":"Negar con don't y doesn't.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u09-l03","unit_id":"a1-u09","position":4,"title_es":"Hoy, mañana y las partes del día","objective_es":"Today, tomorrow, morning, afternoon y evening.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u09-l04","unit_id":"a1-u09","position":5,"title_es":"¿Qué hora es?","objective_es":"Decir la hora con o'clock y half past.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u10-l02","unit_id":"a1-u10","position":2,"title_es":"Lugares para ir","objective_es":"Restaurante, supermercado, negocio, museo, cine y biblioteca.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u10-l05","unit_id":"a1-u10","position":7,"title_es":"Doblá a la izquierda","objective_es":"Dar indicaciones: left, right, turn y straight on.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u11-l02","unit_id":"a1-u11","position":2,"title_es":"Me encanta, lo odio","objective_es":"Love, hate y don’t like.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u11-l03","unit_id":"a1-u11","position":4,"title_es":"Pasatiempos","objective_es":"Bailar, cantar, nadar, cocinar y viajar.","intro":null,"takeaways":[],"_from":"20261119120000"},{"id":"a1-u12-l03","unit_id":"a1-u12","position":4,"title_es":"En clase","objective_es":"Pedir ayuda: repetir, hablar despacio y no entender.","intro":null,"takeaways":[],"_from":"20261119120000"}]$l$::jsonb)
